checks<-list();add<-function(item,pass,detail=''){checks[[length(checks)+1L]]<<-data.table(item=item,status=if(all(pass))'PASS'else'FAIL',detail=as.character(detail))}
md<-qread(out('00_audit/cell_metadata.qs'));sizes<-fread(out('01_partitions/all_cluster_sizes.tsv'));met<-fread(out('02_coverage/all_clusters_two_high.tsv'));precise<-copy(met);precise[,`:=`(precision=TP/n_cluster,recall=TP/n_high,F1=2*TP/(n_cluster+n_high),enrichment=(TP/n_cluster)/(n_high/n_full))];saveq(precise,'02_coverage/all_cluster_metrics_full_precision.qs');can<-fread(out('03_candidates/candidates_preDE.tsv'));ct<-fread(out('03_candidates/comparisons_preDE.tsv'));models<-fread(out('04_pseudobulk_markers/model_summary.tsv'));cov<-fread(out('02_coverage/candidate_source_coverage.tsv'))
add('FULL identity',nrow(md)==123699 & !anyDuplicated(md$cell_id) & uniqueN(md$sample)==57 & uniqueN(md$dataset)==5 & sum(md$source=='Normal')==22436);add('24 partitions',uniqueN(sizes$partition)==24);add('each partition cell sums',sizes[,sum(n_cells),by=partition]$V1==123699);add('fixed high totals',sum(md$NMF_high)==12370 & sum(md$UCell_high)==12372 & sum(md$NMF_high&md$UCell_high)==7002);add('all old partitions reproduced',all(fread(out('00_audit/old_partition_reproduction.tsv'))$reproduced_up_to_permutation));add('all TP sums',met[,.(observed=sum(TP),expected=unique(n_high)),by=.(partition,high)][,all(observed==expected)]);add('all confusion nonnegative',all(as.matrix(met[,.(TP,FP,FN,TN)])>=0));add('all F1 formula',max(abs(met$F1-2*met$TP/(met$n_cluster+met$n_high)))<1e-12)
for(p in unique(sizes$partition)){a<-qread(out(paste0('01_partitions/',p,'.qs')));add(paste(p,'ID alignment and member hashes'),identical(a$cell_id,md$cell_id) & all(a[,.(member_hash=memberhash(cell_id)),by=cluster][sizes[partition==p],on='cluster',member_hash==i.member_hash]))}
rank<-copy(met);setorderv(rank,c('partition','high','F1','minPR','precision','cluster_numeric'),c(1,1,-1,-1,-1,1));wins<-rank[,.SD[1],by=.(partition,high)];add('fixed per-partition winners',setequal(wins$result_id,can$result_id));add('all candidates have rest and local',ct[,all(c('rest','local')%in%control_type),by=candidate_id]$V1 & uniqueN(ct$candidate_id)==nrow(can));add('each comparison has model status',setequal(ct$comparison_id,models$comparison_id)&!anyNA(models$status));add('no silently missing candidates',all(can$candidate_id%in%models$candidate_id))
add('all57 sample coverage retained',cov[field=='sample',.N,by=.(candidate_id,high)]$N==57);add('all5 datasets retained',cov[field=='dataset',.N,by=.(candidate_id,high)]$N==5);add('zero high denominator NA recall',cov[n_high==0,all(is.na(recall))]);add('zero candidate denominator NA precision',cov[n_candidate==0,all(is.na(precision))]);add('zero-hit samples recall0',cov[n_high>0&TP==0,all(recall==0)])
fi<-fread(out('00_audit/INPUT_MANIFEST.tsv'),colClasses=c(mtime='character'));now<-file.info(fi$path);add('readonly input sizes unchanged',now$size==fi$bytes);add('readonly input mtimes unchanged',format(now$mtime,'%Y-%m-%d %H:%M:%OS6 %z')==fi$mtime)
tot<-qread(out('04_pseudobulk_markers/sample_totals.qs'));nn<-md[,.(features=sum(nFeature_counts),counts=sum(nCount_counts),cells=.N),by=sample];nn<-nn[match(tot$meta$sample,sample)];add('sample count totals match original metadata',all(colSums(tot$counts)==nn$counts));add('detected sums match original positive-feature counts',all(colSums(tot$detected_sum)==nn$features),'Also rules out counting explicit stored zero entries as detections');add('sample cell totals',tot$meta$n_cells==nn$cells)
for(k in unique(models$model_key)){d<-paste0('04_pseudobulk_markers/models/',k,'/');st<-fread(out(paste0(d,'status.tsv')));el<-fread(out(paste0(d,'eligibility.tsv')));add(paste(k,'complete eligibility'),nrow(el)==57 & all(el$eligible==(el$n_left>=30&el$n_right>=30)));add(paste(k,'checkpoint exists'),file.exists(out(paste0(d,'COMPLETE'))));if(st$status=='COMPLETE'){r<-fread(out(paste0(d,'DE_full.tsv.gz')));f<-fread(out(paste0(d,'filter.tsv.gz')));add(paste(k,'DE finite and BH'),all(is.finite(r$log2FC)) & all(is.finite(r$PValue)) & max(abs(r$FDR-p.adjust(r$PValue,'BH')))<1e-10);add(paste(k,'tested IDs and pair count'),setequal(r$gene_id,f[tested==TRUE,gene_id]) & unique(r$n_samples)==sum(el$eligible) & st$n_pairs>=3);sh<-fread(out(paste0(d,'shortlist.tsv')));add(paste(k,'shortlist rules'),nrow(sh)<=20 & all(sh$FDR<.05 & sh$log2FC>=.5 & sh$pct_left>=.1 & sh$positive_fraction>=.7));fg<-fread(out(paste0('05_function/',k,'/enrichment_all.tsv.gz')));add(paste(k,'functional results retained'),all(c('NES','padj','leadingEdge','leading_edge_input_genes')%in%names(fg)));rk<-fread(out(paste0(d,'rank_mapping.tsv.gz')));add(paste(k,'all tested rank IDs'),setequal(rk$gene_id,r$gene_id)&!anyDuplicated(rk[mapping_reason=='eligible',gene_symbol]));add(paste(k,'positive residual df'),st$residual_df>0)}else add(paste(k,'explicit not-testable reason'),nzchar(st$reason)&st$status=='NOT_TESTABLE')}
idx<-fread(out('07_figures/figure_index.tsv'));add('all figure pairs/data exist',file.exists(c(idx$pdf,idx$png,idx$plot_data)));pdfpages<-vapply(idx$pdf,function(p)pdftools::pdf_info(p)$pages,integer(1));add('all PDF readable',pdfpages==1);add('all datasets have figures',vapply(unique(md$dataset),function(ds)any(startsWith(idx$figure,paste0(ds,'__'))),logical(1)))
final<-fread(out('08_review/FINAL_CANDIDATES.tsv'));add('38 complete candidate review rows',nrow(final)==nrow(can)&setequal(final$candidate_id,can$candidate_id));dm<-fread(out('08_review/display_marker_evidence.tsv'));add('display max3',if(nrow(dm))dm[,.N,by=candidate_id]$N<=3 else TRUE)
